import { Howl, Howler } from 'howler';
import { useSettings } from '../../stores/settings';

/**
 * Audio built on Howler.js with its spatial (Web Audio panner) support.
 * Every file in /public/audio is generated by scripts/gen-audio.mjs.
 */
const SFX = [
  'heartbeat', 'step_soft', 'step_hard', 'step_heavy', 'swing', 'hit', 'hurt', 'down', 'roar', 'gen_loop', 'gen_fail',
  'gen_done', 'power_on', 'door', 'pallet', 'locker', 'key', 'alarm', 'skill_warn', 'skill_good', 'skill_great',
  'skill_fail', 'ui_click', 'ui_hover', 'flashlight', 'shadow_step', 'charge', 'echo', 'firecracker', 'escape',
  'eliminated', 'whisper', 'breath', 'cage',
] as const;
const MUSIC = ['ambient_forest', 'ambient_asylum', 'music_tension', 'music_chase'] as const;
export type SfxName = (typeof SFX)[number];
export type MusicName = (typeof MUSIC)[number];

const howls = new Map<string, Howl>();
let loaded = false;

function load() {
  if (loaded) return;
  loaded = true;
  for (const n of SFX) howls.set(n, new Howl({ src: [`/audio/${n}.wav`], preload: true, loop: n === 'gen_loop' || n === 'heartbeat' }));
  for (const n of MUSIC) howls.set(n, new Howl({ src: [`/audio/${n}.wav`], preload: true, loop: true, volume: 0 }));
  applyVolumes();
}

export function applyVolumes() {
  const s = useSettings.getState();
  Howler.volume(s.muted ? 0 : s.masterVolume);
}
useSettings.subscribe(applyVolumes);

const sfxVol = () => useSettings.getState().sfxVolume;
const musicVol = () => useSettings.getState().musicVolume;

export const audio = {
  unlock() {
    load();
    Howler.ctx?.resume?.();
  },
  ui(name: 'ui_click' | 'ui_hover') {
    if (!loaded) return;
    howls.get(name)?.volume(0.35 * sfxVol());
    howls.get(name)?.play();
  },
  /** Non-positional one-shot (UI, your own actions). */
  play(name: SfxName, volume = 1, rate = 1) {
    load();
    const h = howls.get(name);
    if (!h) return -1;
    const id = h.play();
    h.volume(Math.min(1, volume * sfxVol()), id);
    h.rate(rate, id);
    return id;
  },
  /** Positional one-shot at a world position. */
  at(name: SfxName, x: number, z: number, volume = 1, rate = 1, y = 1) {
    load();
    const h = howls.get(name);
    if (!h) return -1;
    const id = h.play();
    h.volume(Math.min(1, volume * sfxVol()), id);
    h.rate(rate, id);
    h.pos(x, y, z, id);
    h.pannerAttr({ panningModel: 'equalpower', refDistance: 2.5, maxDistance: 70, rolloffFactor: 1.3, distanceModel: 'inverse' }, id);
    return id;
  },
  /** Start or update a positional loop identified by `key`. */
  loopAt(key: string, name: SfxName, x: number, z: number, volume: number) {
    load();
    const h = howls.get(name);
    if (!h) return;
    let id = loops.get(key);
    if (id === undefined) {
      id = h.play();
      h.loop(true, id);
      h.pannerAttr({ panningModel: 'equalpower', refDistance: 2, maxDistance: 40, rolloffFactor: 1.5, distanceModel: 'inverse' }, id);
      loops.set(key, id);
      loopNames.set(key, name);
    }
    h.pos(x, 1, z, id);
    h.volume(volume * sfxVol(), id);
  },
  stopLoop(key: string) {
    const id = loops.get(key);
    const name = loopNames.get(key);
    if (id !== undefined && name) howls.get(name)?.stop(id);
    loops.delete(key);
    loopNames.delete(key);
  },
  /** Global (non-positional) loop with smooth volume. */
  bed(name: MusicName | 'heartbeat', target: number, rate = 1) {
    load();
    const h = howls.get(name);
    if (!h) return;
    const vol = target * (name === 'heartbeat' ? sfxVol() : musicVol());
    let id = beds.get(name);
    if (id === undefined) {
      if (vol <= 0.001) return;
      id = h.play();
      h.loop(true, id);
      h.volume(0, id);
      beds.set(name, id);
    }
    const cur = h.volume(id) as number;
    h.volume(cur + (vol - cur) * 0.08, id);
    h.rate(rate, id);
  },
  listener(x: number, y: number, z: number, yaw: number) {
    if (!loaded) return;
    Howler.pos(x, y, z);
    Howler.orientation(-Math.sin(yaw), 0, -Math.cos(yaw), 0, 1, 0);
  },
  stopAll() {
    for (const [key] of loops) audio.stopLoop(key);
    for (const [name, id] of beds) howls.get(name)?.stop(id);
    beds.clear();
  },
};

const loops = new Map<string, number>();
const loopNames = new Map<string, SfxName>();
const beds = new Map<string, number>();
